 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const group = new Group();
  group.name = config.id || 'journal-card-3-label';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';

  const src = config.atlasRegion?.sourceRect;
  const srcW = src?.[2] ?? 512;
  const srcH = src?.[3] ?? 320;
  const aspect = srcW / srcH || 1.6;

  const cardHeight = 0.75;
  const cardWidth = cardHeight * aspect;

  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/floating-accent.png';

  let loadedTex = null;

  const uHover = uniform(0.0);
  const uEdge = uniform(0.0);

  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });

  const texPromise = ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.needsUpdate = true;
    loadedTex = tex;

    const texNode = texture(tex, uv());
    cardMat.colorNode = texNode.rgb;
    cardMat.opacityNode = texNode.a;
  });

  const card = new Mesh(cardGeo, cardMat);
  card.name = 'card-plane';
  group.add(card);

  const edgeGeo = new PlaneGeometry(cardWidth + 0.04, cardHeight + 0.04);
  const edgeMat = new MeshBasicNodeMaterial({ transparent: true });
  edgeMat.colorNode = color(accent);
  edgeMat.opacityNode = uEdge;
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.name = 'accent-edge';
  edge.position.z = -0.01;
  group.add(edge);

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textItems[0] ?? { text: 'Journal 3', typography: { fontSize: 39 } };

  const textMesh = ctx.fontAtlas.createText(textItem.text ?? 'Journal 3', {
    fontSize: textItem.typography?.fontSize ?? 39,
    color: paper,
    align: 'center'
  });
  textMesh.name = 'label-text';
  textMesh.position.z = 0.02;
  group.add(textMesh);

  const primRefs = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives?.[p.name]) {
      primRefs.push(ctx.primitives[p.name](group, p.params ?? {}));
    }
  }

  const activeTweens = new Set();
  function track(tween) {
    activeTweens.add(tween);
    tween.eventCallback('onComplete', () => activeTweens.delete(tween));
    return tween;
  }

  function killAll() {
    activeTweens.forEach(t => t?.kill());
    activeTweens.clear();
  }

  function riseIn() {
    track(gsap.to(group.position, { y: 0.15, duration: 0.5, ease: 'power2.out' }));
    track(gsap.to(uEdge, { value: 0.9, duration: 0.3, ease: 'power2.out' }));
  }

  function settle() {
    track(gsap.to(group.position, { y: 0, duration: 0.5, ease: 'power2.out' }));
    track(gsap.to(uEdge, { value: 0, duration: 0.3, ease: 'power2.out' }));
  }

  function pressDown() {
    track(gsap.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' }));
    track(gsap.to(uEdge, { value: 1.0, duration: 0.1, ease: 'power2.out' }));
  }

  function release() {
    track(gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out(1.7)' }));
    track(gsap.to(uEdge, { value: 0.9, duration: 0.1, ease: 'power2.out' }));
  }

  group.userData.handlers = {
    pointerenter: riseIn,
    pointerover: riseIn,
    pointerleave: settle,
    pointerout: settle,
    pointerdown: pressDown,
    pointerup: release,
    click: () => ctx.emit('hub-journal.select', { from: config.id })
  };

  group.userData.cleanup = () => {
    killAll();
    primRefs.forEach(r => r?.cleanup?.());
    cardGeo.dispose();
    edgeGeo.dispose();
    cardMat.dispose();
    edgeMat.dispose();
    if (loadedTex) loadedTex.dispose();
    group.removeFromParent();
  };

  return group;
}
